import{_ as e,o as a,c as o,a6 as r}from"./chunks/framework.O8w_gp-L.js";const p=JSON.parse('{"title":"Playing together","description":"","frontmatter":{},"headers":[],"relativePath":"guides/playing-together.md","filePath":"guides/playing-together.md"}'),n={name:"guides/playing-together.md"};function s(i,t,g,l,h,d){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="playing-together" tabindex="-1">Playing together <a class="header-anchor" href="#playing-together" aria-label="Permalink to &quot;Playing together&quot;">​</a></h1><p>Clear <strong>1-2 Dyers Wharf</strong> to open <strong>Social</strong>, <strong>Party</strong> and <strong>Play together</strong>. Up to <strong>three fighters</strong> can play a stage together.</p><h2 id="starting-a-stage-together" tabindex="-1">Starting a stage together <a class="header-anchor" href="#starting-a-stage-together" aria-label="Permalink to &quot;Starting a stage together&quot;">​</a></h2><ul><li>Open the chapter map at the <strong>Stage Gate</strong> and pick a stage.</li><li>Choose <strong>Play with</strong> and a friend&#39;s name to ask a fighter who is free in Loomhaven.</li><li>They see that you <strong>want to play</strong> and have 15 seconds to press <strong>Join</strong> (or <strong>Not now</strong>).</li><li>Everyone needs to have reached the stage. If not, the game says they <strong>haven&#39;t reached this stage yet</strong>.</li></ul><h2 id="lives-in-a-party" tabindex="-1">Lives in a party <a class="header-anchor" href="#lives-in-a-party" aria-label="Permalink to &quot;Lives in a party&quot;">​</a></h2><ul><li>Your party shares one pool of revives, shown as <strong>Revives</strong> on screen. On Hard the pool is one smaller.</li><li>Knocked down? Hold on: a teammate can <strong>Relight</strong> you. Stand next to a downed friend and press <strong>Z</strong> (<strong>G</strong> with WASD keys, or the round <strong>Interact</strong> button on touch).</li><li>Dropped out? Rejoin within 2 minutes on the same fighter to get back in.</li><li>A second friend can still join on the first screen.</li></ul><h2 id="after-a-clear" tabindex="-1">After a clear <a class="header-anchor" href="#after-a-clear" aria-label="Permalink to &quot;After a clear&quot;">​</a></h2><ul><li>Everyone who was there at the clear gets paid, even if they were knocked down.</li><li>On the card, everyone picks <strong>Replay</strong>, <strong>Next</strong> or <strong>Loomhaven</strong> (or <strong>Opt out</strong>). Pick the same thing, then the leader presses <strong>Go</strong>.</li></ul><h2 id="co-op-tricks" tabindex="-1">Co-op tricks <a class="header-anchor" href="#co-op-tricks" aria-label="Permalink to &quot;Co-op tricks&quot;">​</a></h2><ul><li><strong>Relays:</strong> launch a foe and let a teammate catch it with an air hit or <strong>Air Slam</strong> within about a second. You&#39;ll see <strong>Relay!</strong>: that hit does more damage and adds score.</li><li><strong>Party bonus:</strong> land 3 relays with no knockouts and everyone gets 20 silver.</li><li>A shared combo can keep going while teammates keep hitting.</li></ul><p><strong>Hard mode</strong> opens after you clear <strong>1-5</strong> on Normal, and takes up to three fighters. Everyone needs that stage open on Hard.</p><p>Looking for people? Post in &lt;#LFG&gt;.</p>',12)])])}const u=e(n,[["render",s]]);export{p as __pageData,u as default};
